// one-off: measure the rendered boxes that the requirements talk about
import fs from "node:fs"
import http from "node:http"
import path from "node:path"
import { chromium } from "playwright-core"
const OUT = path.resolve(".build")
const MIME = { ".png": "image/png", ".svg": "image/svg+xml", ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json", ".woff2": "font/woff2" }
const server = http.createServer((req, res) => {
  const p = path.join(OUT, decodeURIComponent(new URL(req.url, "http://x").pathname))
  if (!p.startsWith(OUT) || !fs.existsSync(p) || fs.statSync(p).isDirectory()) return res.writeHead(404).end()
  res.writeHead(200, { "content-type": MIME[path.extname(p)] ?? "application/octet-stream" })
  fs.createReadStream(p).pipe(res)
})
await new Promise((r) => server.listen(0, "127.0.0.1", r))
const b = await chromium.launch({ executablePath: process.env.CHROMIUM_PATH ?? "/opt/pw-browsers/chromium" })
const page = await b.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto(`http://127.0.0.1:${server.address().port}/index.html`)
await page.waitForFunction(() => window.__READY__ === true, null, { timeout: 30000 })
const out = await page.evaluate(() => {
  const box = (el) => { const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) } }
  const q = (s) => [...document.querySelectorAll(s)]
  return {
    body: box(document.querySelector("[data-slot=section-body]")),
    table: box(document.querySelector("[data-slot=custom-table] table")),
    caption: box(document.querySelector("[data-slot=table-caption]")),
    bars: q("[data-slot=progress]").slice(0, 3).map(box),
    barHeights: q("[data-slot=progress]").slice(0, 3).map((e) => getComputedStyle(e).height),
    strips: q("[data-slot=figure-strip]").map(box),
    stripRowWidths: q("[data-slot=figure-strip-row]").map((e) => Math.round(e.scrollWidth)),
    stripImgs: q("[data-slot=figure-strip] img").map(box),
    grid: box(document.querySelector("[data-slot=figure-grid]")),
    gridFigures: q("[data-slot=figure-grid] > [data-slot=figure]").map(box),
    gridImgs: q("[data-slot=figure-grid] img").map(box),
    scrollbars: q("[data-slot=scroll-area-scrollbar]").map((e) => ({ ...box(e), state: e.dataset.state })),
    tone: q("[data-slot=custom-table] td").filter((e) => e.className.includes("destructive")).map((e) => ({ text: e.textContent, weight: getComputedStyle(e).fontWeight, color: getComputedStyle(e).color })),
    plain: q("[data-slot=custom-table] td").filter((e) => e.textContent === "中等").map((e) => ({ text: e.textContent, weight: getComputedStyle(e).fontWeight, color: getComputedStyle(e).color })),
  }
})
console.log(JSON.stringify(out, null, 1))
await b.close(); server.close()
